		return func(c Context) error { c.Response().Header().Set("X-MW", "1"); return next(c) }
	}
	g := e.Group("/g", mw)
	g.GET("/x", func(c Context) error { return c.String(http.StatusOK, "x") })

	// unmatched path under group -> catch-all NotFoundHandler, middleware runs
	req := httptest.NewRequest(http.MethodGet, "/g/nope", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	t.Logf("GET /g/nope -> %d mw=%q", rec.Code, rec.Header().Get("X-MW"))
	if rec.Code != http.StatusNotFound || rec.Header().Get("X-MW") != "1" {
		t.Fatalf("catch-all middleware not applied: %d %q", rec.Code, rec.Header().Get("X-MW"))
	}
	// registered route still works
	req = httptest.NewRequest(http.MethodGet, "/g/x", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	t.Logf("GET /g/x -> %d body=%q mw=%q", rec.Code, rec.Body.String(), rec.Header().Get("X-MW"))
	if rec.Code != http.StatusOK || rec.Body.String() != "x" || rec.Header().Get("X-MW") != "1" {
		t.Fatalf("registered route broken: %d %q %q", rec.Code, rec.Body.String(), rec.Header().Get("X-MW"))
	}
}
